func loadSchema(raw []byte) (*schemaDoc, error) {
	var m map[string]any
	if err := json.Unmarshal(raw, &m); err != nil {
		return nil, fmt.Errorf("the walkthrough schema itself is not valid JSON: %w", err)
	}
	return &schemaDoc{root: m}, nil
}

